    {
      "id": "title-slide",
      "title": "Global Renewable Energy in 2025: How Far Have We Come?",
      "objective": "Cover slide with deck title, subtitle summarizing the scope (global renewable energy trends across primary energy and electricity), and source attribution to Our World in Data."
    },
    {
      "id": "fossil-fuel-dominance-context",
      "title": "75% of Global GHG Emissions Still Come from Fossil Fuels",
      "objective": "Set the context: fossil fuels dominate the energy mix since the Industrial Revolution, driving climate change and 5 million+ premature deaths annually from air pollution. Use a concise text-and-icon layout to convey urgency."
    },
    {
      "id": "renewables-primary-energy-share",
      "title": "Renewables Now Supply ~14% of Global Primary Energy",
      "objective": "Show the share of primary energy from renewables globally as of 2024 using the world map visualization. Reference the substitution method. Highlight that approximately one-seventh of primary energy is renewable. Use figure_2.jpg (map)."
    },
    {
      "id": "renewable-electricity-generation-growth",
      "title": "Renewable Electricity Generation Is Growing Rapidly, Led by Wind and Solar",
      "objective": "Present the breakdown of renewable electricity generation by technology (hydro ~4,500 TWh, wind ~2,400 TWh, solar ~2,000 TWh, other ~700 TWh) using the data table from the brief. Emphasize the acceleration in wind and solar since ~2010 and note that wind and solar combined now nearly match hydropower's output. Use a bar or column chart layout to visualize the generation data by technology."
    },
    {
      "id": "electricity-mix-one-third-renewable",
      "title": "Almost One-Third of Global Electricity Now Comes from Renewables",
      "objective": "Show the share of electricity from renewables by country using the world map (figure_1.jpg). Highlight regional leaders (e.g., Brazil, Canada, Nordics at 60–90%+; Middle East and parts of Asia below 10%). Include a small data table of selected countries."
    },
    {
      "id": "hydropower-still-largest-source",
      "title": "Hydropower Remains the Largest Renewable Source at ~50% of Generation",
      "objective": "Dedicated slide on hydropower's dominant role. Show the map of hydropower generation (figure_6.jpg) and note top producers (China, Brazil, Canada). Mention that hydro accounts for roughly half of all renewable electricity."
    },
    {
      "id": "wind-and-solar-fastest-growing",
      "title": "Wind and Solar Are the Fastest-Growing Energy Technologies in History",
      "objective": "Highlight the rapid growth of wind and solar generation. Use figure_8.jpg (wind generation map). Present a comparison of wind vs. solar using available data: wind ~2,400 TWh (~25% of renewable electricity) vs. solar ~2,000 TWh (~21% of renewable electricity), noting solar is the fastest-growing source with dramatic growth since 2010 driven by falling costs and policy support. Emphasize that wind and solar combined now nearly match hydropower output."
    },
    {
      "id": "regional-disparities-access-gap",
      "title": "Stark Regional Gaps: Sub-Saharan Africa Lags While Scandinavia and Latin America Lead",
      "objective": "Use figure_3.jpg (share of electricity from hydropower by country) to illustrate how hydropower access varies regionally, and reference the electricity data table to show that many African and Middle Eastern countries have renewable electricity shares below 10%, while Scandinavia, Brazil, and Canada lead at 65–98%. Discuss the uneven transition: Scandinavian countries and Brazil benefit from abundant hydropower, Denmark and Germany have invested heavily in wind and solar, while Sub-Saharan Africa has minimal renewable infrastructure and Middle Eastern nations remain almost entirely fossil-fuel dependent."
    },
    {
      "id": "key-takeaways",
      "title": "Key Takeaways: Renewables Are Growing Fast but the Transition Must Accelerate",
      "objective": "Summarize 4–5 key findings: renewables at ~14% of primary energy and ~30% of electricity; hydro still dominant but wind/solar catching up; significant regional disparities remain; transport and heating lag behind electricity in decarbonization. End with a forward-looking statement on the pace needed."
    }
  ]
}

