const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const path = require("path");

// Icons
const { FaIndustry, FaSkullCrossbones, FaGlobeAmericas, FaBolt, FaWater, FaWind, FaSolarPanel, FaExclamationTriangle, FaArrowUp, FaCheckCircle, FaChartBar } = require("react-icons/fa");

function renderIconSvg(IconComponent, color, size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette - Forest & green energy theme
const C = {
  darkBg: "1B3A2D",
  medBg: "245840",
  lightBg: "F4F7F5",
  cardBg: "FFFFFF",
  accent: "2E8B57",    // sea green
  accent2: "F4A236",   // amber
  accent3: "3A9BD5",   // blue
  title: "FFFFFF",
  darkTitle: "1B3A2D",
  body: "2D3436",
  muted: "636E72",
  subtle: "B2BEC3",
  tableHead: "2E8B57",
  tableAlt: "EDF5F0",
};

const FONTS = { head: "Georgia", body: "Calibri" };
const ASSETS = "/app/benchmark/assets";

function makeShadow() {
  return { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.12 };
}

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Data Analytics Team";
  pres.title = "Global Renewable Energy in 2025: How Far Have We Come?";

  // Pre-render icons
  const icons = {};
  const iconDefs = [
    ["industry", FaIndustry, "#" + C.accent2],
    ["skull", FaSkullCrossbones, "#FF6B6B"],
    ["globe", FaGlobeAmericas, "#FFFFFF"],
    ["bolt", FaBolt, "#" + C.accent2],
    ["water", FaWater, "#3A9BD5"],
    ["wind", FaWind, "#5DADE2"],
    ["solar", FaSolarPanel, "#F4A236"],
    ["arrow", FaArrowUp, "#2E8B57"],
    ["check", FaCheckCircle, "#2E8B57"],
    ["chart", FaChartBar, "#FFFFFF"],
    ["warning", FaExclamationTriangle, "#F4A236"],
  ];
  for (const [name, comp, color] of iconDefs) {
    icons[name] = await iconToBase64Png(comp, color);
  }

  // ============ SLIDE 1: Title ============
  let s1 = pres.addSlide();
  s1.background = { color: C.darkBg };
  // decorative shape
  s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 1.2, fill: { color: C.medBg } });
  s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.4, w: 10, h: 1.225, fill: { color: C.medBg } });
  s1.addImage({ data: icons.globe, x: 0.6, y: 0.25, w: 0.6, h: 0.6 });
  s1.addText("OUR WORLD IN DATA", { x: 1.4, y: 0.25, w: 5, h: 0.6, fontFace: FONTS.body, fontSize: 14, color: C.subtle, valign: "middle", charSpacing: 3, margin: 0 });
  s1.addText("Global Renewable Energy in 2025", { x: 0.6, y: 1.6, w: 8.8, h: 1.1, fontFace: FONTS.head, fontSize: 38, color: C.title, bold: true, margin: 0 });
  s1.addText("How Far Have We Come?", { x: 0.6, y: 2.7, w: 8.8, h: 0.7, fontFace: FONTS.head, fontSize: 28, color: C.accent2, italic: true, margin: 0 });
  s1.addText("A data-driven overview of renewable energy\u2019s growing share in the global energy and electricity mix", { x: 0.6, y: 3.5, w: 7, h: 0.7, fontFace: FONTS.body, fontSize: 14, color: C.subtle, margin: 0 });
  s1.addText("Sources: Ember (2026); Energy Institute \u2013 Statistical Review of World Energy (2025)", { x: 0.6, y: 4.6, w: 8, h: 0.4, fontFace: FONTS.body, fontSize: 10, color: C.subtle, margin: 0 });
  s1.addText("For policy analysts and energy sector strategists", { x: 0.6, y: 5.0, w: 8, h: 0.3, fontFace: FONTS.body, fontSize: 10, color: C.muted, italic: true, margin: 0 });

  // ============ SLIDE 2: Fossil Fuel Context ============
  let s2 = pres.addSlide();
  s2.background = { color: C.lightBg };
  // Title bar
  s2.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 1.0, fill: { color: C.darkBg } });
  s2.addText("75% of Global GHG Emissions Still Come from Fossil Fuels", { x: 0.6, y: 0.1, w: 8.8, h: 0.8, fontFace: FONTS.head, fontSize: 24, color: C.title, bold: true, margin: 0 });
  // Two stat cards
  const cardY = 1.4;
  // Card 1: GHG
  s2.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: cardY, w: 4.2, h: 2.4, fill: { color: C.cardBg }, shadow: makeShadow() });
  s2.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: cardY, w: 4.2, h: 0.08, fill: { color: C.accent2 } });
  s2.addImage({ data: icons.industry, x: 1.0, y: cardY + 0.3, w: 0.5, h: 0.5 });
  s2.addText("75%", { x: 1.7, y: cardY + 0.2, w: 2.5, h: 0.7, fontFace: FONTS.head, fontSize: 42, color: C.accent2, bold: true, margin: 0 });
  s2.addText("of global greenhouse gas emissions come from burning fossil fuels for energy", { x: 1.0, y: cardY + 1.0, w: 3.4, h: 1.0, fontFace: FONTS.body, fontSize: 13, color: C.body, margin: 0 });
  // Card 2: Deaths
