    ["Stark regional disparities persist:", "Scandinavia/Latin America at 60\u201390%+ vs. Middle East/Sub-Saharan Africa below 10%."],
    ["Transport & heating lag far behind", "electricity, keeping overall primary energy share much lower."],
  ];

  let ty = 1.5;
  for (const [bold, rest] of takeaways) {
    s9.addImage({ data: icons.check, x: 0.6, y: ty + 0.05, w: 0.3, h: 0.3 });
    s9.addText([
      { text: bold + " ", options: { bold: true, color: C.title } },
      { text: rest, options: { color: C.subtle } }
    ], { x: 1.1, y: ty, w: 8.3, h: 0.65, fontFace: FONTS.body, fontSize: 13, margin: 0 });
    ty += 0.7;
  }

  s9.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.8, w: 10, h: 0.825, fill: { color: C.medBg } });
  s9.addText("The pace of the renewable transition must accelerate to meet global climate targets. Every policy decision matters.", { x: 0.6, y: 4.9, w: 8.8, h: 0.5, fontFace: FONTS.body, fontSize: 14, color: C.accent2, italic: true, bold: true, margin: 0 });

  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Deck saved to /app/output/final_deck.pptx");
}

main().catch(e => { console.error(e); process.exit(1); });

